'use client'

import { useId, useState } from 'react'
import type { ChangeEvent, CSSProperties, InputHTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

type RetroSliderProps = Omit<InputHTMLAttributes<HTMLInputElement>, 'type'> & {
  label?: string
  showValue?: boolean
}

export function RetroSlider({
  label,
  showValue = true,
  min = 0,
  max = 100,
  value,
  defaultValue,
  onChange,
  className,
  id,
  ...props
}: RetroSliderProps) {
  const autoId = useId()
  const inputId = id ?? autoId
  const [internal, setInternal] = useState(Number(defaultValue ?? min))
  const current = value !== undefined ? Number(value) : internal
  const range = Number(max) - Number(min)
  const fill = range > 0 ? ((current - Number(min)) / range) * 100 : 0

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    setInternal(Number(event.target.value))
    onChange?.(event)
  }

  return (
    <div className="flex flex-col gap-1">
      {label || showValue ? (
        <div className="flex items-baseline justify-between gap-3">
          {label ? (
            <label htmlFor={inputId} className="font-medium">
              {label}
            </label>
          ) : (
            <span />
          )}
          {showValue ? (
            <output htmlFor={inputId} className="font-mono text-[12px] text-rt-ink">
              {current}
            </output>
          ) : null}
        </div>
      ) : null}
      <input
        id={inputId}
        type="range"
        min={min}
        max={max}
        {...(value !== undefined ? { value } : { defaultValue: defaultValue ?? min })}
        onChange={handleChange}
        style={{ '--rt-fill': `${fill}%` } as CSSProperties}
        className={cn('rt-range w-full', className)}
        {...props}
      />
    </div>
  )
}

'use client'

import { useId, useRef, useState } from 'react'
import type { KeyboardEvent, ReactNode } from 'react'
import { cn } from '@/lib/utils'

export type RetroTab = { id: string; label: string; content: ReactNode }

type RetroTabsProps = {
  tabs: RetroTab[]
  value?: string
  onValueChange?: (id: string) => void
  className?: string
  panelClassName?: string
}

export function RetroTabs({ tabs, value, onValueChange, className, panelClassName }: RetroTabsProps) {
  const baseId = useId()
  const [inner, setInner] = useState(tabs[0]?.id)
  const active = value ?? inner
  const buttons = useRef<Record<string, HTMLButtonElement | null>>({})

  function setActive(id: string) {
    setInner(id)
    onValueChange?.(id)
  }

  function onKeyDown(event: KeyboardEvent, index: number) {
    const step = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : 0
    if (!step) return
    event.preventDefault()
    const next = tabs[(index + step + tabs.length) % tabs.length]
    setActive(next.id)
    buttons.current[next.id]?.focus()
  }

  return (
    <div className={cn('flex flex-col', className)}>
      <div role="tablist" className="flex items-end gap-0.5 px-1">
        {tabs.map((tab, index) => {
          const selected = tab.id === active
          return (
            <button
              key={tab.id}
              ref={(node) => {
                buttons.current[tab.id] = node
              }}
              id={`${baseId}-tab-${tab.id}`}
              role="tab"
              type="button"
              aria-selected={selected}
              aria-controls={`${baseId}-panel-${tab.id}`}
              tabIndex={selected ? 0 : -1}
              onClick={() => setActive(tab.id)}
              onKeyDown={(event) => onKeyDown(event, index)}
              className={cn(
                'rt-raised relative rounded-b-none px-3.5 text-[13px] font-medium transition-[filter] hover:brightness-105',
                'focus-visible:outline-2 focus-visible:-outline-offset-4 focus-visible:outline-rt-accent',
                selected ? 'z-10 -mb-px h-7.5 border-b-rt-face bg-rt-face' : 'h-6.5 text-rt-ink/75',
              )}
            >
              {tab.label}
            </button>
          )
        })}
      </div>
      {tabs.map((tab) => (
        <div
          key={tab.id}
          id={`${baseId}-panel-${tab.id}`}
          role="tabpanel"
          aria-labelledby={`${baseId}-tab-${tab.id}`}
          hidden={tab.id !== active}
          className={panelClassName ?? 'rt-raised rounded-[3px] p-3'}
        >
          {tab.content}
        </div>
      ))}
    </div>
  )
}

